INSERT INTO CUSTOMERS (ID, NAME) VALUES (2, 'B');
INSERT INTO ORDERS (ID, CUSTOMERID) VALUES (1, '1');
INSERT INTO ORDERS (ID, CUSTOMERID) VALUES (2, NULL);

